# Générateur des silhouettes dessinées (sprite SVG) — Réseau vivant
# Usage : python3 tools/generer-silhouettes.py sprite.svg  (le sprite est ensuite collé dans index.html)
# Dessins originaux (formes géométriques simples), aucun droit d'auteur tiers.
# Toutes les formes regardent vers la droite, viewBox 0 -14 100 82, sol à y=64.
import json
OUT={}
def P(d,cls=''): return f'<path d="{d}"{(" class=%s"%chr(34)+cls+chr(34)) if cls else ""}/>'
def E_(cx,cy,rx,ry,rot=0): return f'<ellipse cx="{cx}" cy="{cy}" rx="{rx}" ry="{ry}"'+(f' transform="rotate({rot} {cx} {cy})"' if rot else '')+'/>'
def C(cx,cy,r): return f'<circle cx="{cx}" cy="{cy}" r="{r}"/>'
def scale(s,body,ox=50,gy=64): return f'<g transform="translate({ox} {gy}) scale({s}) translate(-{ox} -{gy})">{body}</g>'
def flip(body): return f'<g transform="translate(100 0) scale(-1 1)">{body}</g>'

# ---------- antilopes ----------
LEGS = P('M60,34 L67,34 L65,64 L61.5,64Z')+P('M52,36 L58,36 L57,63 L54,63Z')+P('M19,28 L33,33 L30,50 L28,64 L24.5,64 L25.5,48Z')+P('M30,38 L37,38 L33,63 L30,63Z')
