TAIL = P('M18,26 L11,34 L20,31Z')
NECK = P('M58,26 L70,27 L81,12 L74,8Z')
HEAD = P('M73,8 L84,7 L94,16 L91,20 L83,19 L75,15Z')
EAR = P('M74,9 L67,4 L77,6Z')
H = {
 'sabre': P('M79,8 Q74,-8 56,-6 L56.5,-3 Q71,-4 82,8Z'),
 'sabre_court': P('M79,8 Q75,-5 63,-5 L64,-2 Q73,-2 82,8Z'),
 'lyre': P('M77,8 Q66,-4 75,-14 L77.5,-13 Q71,-5 80,7Z')+P('M80,8 Q73,-2 84,-12 L86,-10 Q79,-3 83,7Z'),
 'spirale': P('M78,8 Q70,0 77,-4 Q69,-9 76,-16 L78.5,-15 Q73,-9 80,-4 Q74,0 82,8Z'),
 'droite': P('M80,8 L77,-10 L79.5,-10.5 L83,8Z'),
 'pointe': P('M80,8 Q78,-1 73,-4 L74.5,-6 Q82,-2 83,8Z'),
 'petite': P('M80,8 L79,0 L81.5,0 L83,8Z'),
 'lyre_petite': P('M79,8 Q73,-1 78,-8 L80,-7 Q76,-1 82,7Z'),
 'crochet': P('M76,8 Q66,10 68,-1 L71,0 Q70,6 79,6Z')+P('M81,8 Q91,10 89,-1 L86,0 Q87,6 78,6Z'),
}
def antelope(h,s=1.0,extra='',neck=NECK,hump=False,ox=50):
    b = BODY+LEGS+TAIL+neck+HEAD+EAR+H[h]+extra
    if hump: b += E_(58,25,12,8)
    return scale(s,b,ox)
