def bird(by=28,bx=38,brx=22,bry=13,neck_top=0,head_r=5,beak='',crest='',legs_w=3.5,tail='',wing=True):
    hx=bx+26
    b=E_(bx,by,brx,bry)+P(f'M{bx+12},{by-6} L{bx+19},{by-4} L{hx+2},{neck_top+3} L{hx-4},{neck_top+3}Z')+C(hx,neck_top,head_r)+beak+crest+tail
    for lx in (bx-6,bx+6):
        b+=P(f'M{lx-legs_w/2},{by+bry-3} L{lx+legs_w/2},{by+bry-3} L{lx+1},64 L{lx-1},64Z')+P(f'M{lx-1},62 L{lx+8},64 L{lx-1},64Z')
    if wing: b+='<g class="cut">'+P(f'M{bx-12},{by+2} Q{bx},{by-8} {bx+14},{by+2}')+'</g>'
    return b
